package com.ruoyi.medical.persistence;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;import java.util.*;import java.math.BigInteger;import org.springframework.transaction.support.TransactionSynchronizationManager;import com.ruoyi.medical.identity.BusinessSessionProtocol;import com.ruoyi.medical.contracts.SchemaCatalogue;
import static com.ruoyi.medical.persistence.FormalEvaluationContextSchemaTest.*;
/** Actual closure logic with separately labelled candidate/policy/capability/schema-authority doubles. */
class FormalEvaluationContextDependenciesTest {
 final PermissionSchema json=new PermissionSchema();final FormalAgentCandidateAuthority candidates=mock(FormalAgentCandidateAuthority.class);final FormalAgentCandidateAuthority.VerifiedCandidateIdentity candidate=mock(FormalAgentCandidateAuthority.VerifiedCandidateIdentity.class);
 final AgentExecutionPolicyAuthority policies=mock(AgentExecutionPolicyAuthority.class);final AgentExecutionPolicyAuthority.VerifiedPolicy policy=mock(AgentExecutionPolicyAuthority.VerifiedPolicy.class);final AgentExecutionPolicyProtocol.Definition policyDefinition=mock(AgentExecutionPolicyProtocol.Definition.class);
 final FormalCapabilityIdentityAuthority capabilities=mock(FormalCapabilityIdentityAuthority.class);final FormalCapabilityIdentityAuthority.VerifiedCapability role=mock(FormalCapabilityIdentityAuthority.VerifiedCapability.class),prompt=mock(FormalCapabilityIdentityAuthority.VerifiedCapability.class);
 final FormalRuntimeCapabilityIdentityAuthority components=mock(FormalRuntimeCapabilityIdentityAuthority.class);final FormalRuntimeCapabilityIdentityAuthority.VerifiedCapability assembler=mock(FormalRuntimeCapabilityIdentityAuthority.VerifiedCapability.class);final SchemaCatalogue catalogue=mock(SchemaCatalogue.class);
 final EnterpriseAccess.Admission a=mock(EnterpriseAccess.Admission.class);final FormalEvaluationContextDependencies deps=new FormalEvaluationContextDependencies(candidates,policies,capabilities,components,catalogue,json);
 final com.fasterxml.jackson.databind.node.ObjectNode manifest=json.object(),assembly=json.object();TenantScope scope;
 FormalEvaluationContextDependenciesTest()throws Exception{
  when(a.actorId()).thenReturn(id(101));when(a.context()).thenReturn(new BusinessSessionProtocol.Context(id(100),"1","1","1"));when(candidates.require(a,b(2),id(1),"EVALUATION_RESULTS")).thenReturn(candidate);when(candidate.executionPolicy()).thenReturn(b(3));when(candidate.status()).thenReturn("DRAFT");when(candidate.createdBy()).thenReturn(id(102));when(candidate.classification()).thenReturn("INTERNAL");when(candidate.authorizations()).thenReturn(json.object());when(candidate.manifestDefinition()).thenReturn(manifest);
  manifest.putArray("role_versions").add(json.tree(b(4)));manifest.putArray("prompt_revisions").add(json.tree(b(5)));manifest.putArray("tool_versions").add(json.tree(b(6)));var schemas=manifest.putArray("input_output_schema_refs");for(var direction:List.of("INPUT","OUTPUT")){var entry=schemas.addObject().put("consumer_version_id",id(6)).put("direction",direction);entry.set("schema",json.tree(definition().nodeBindings().get(0).inputSchema()));}
  when(policies.requireByVersion(a,id(3),"a".repeat(64),id(1),"INTERNAL","RUN_CREATION")).thenReturn(policy);when(policy.definition()).thenReturn(policyDefinition);when(policy.authorizations()).thenReturn(json.object());when(policyDefinition.bindings()).thenReturn(List.of(new AgentExecutionPolicyProtocol.NodeBinding("N01",b(4),b(20),b(21),null,json.object(),List.of())));
  when(capabilities.require(a,b(4),"ROLE",id(1),"EVALUATION_RESULTS")).thenReturn(role);when(capabilities.require(a,b(5),"PROMPT",id(1),"EVALUATION_RESULTS")).thenReturn(prompt);when(role.authorizations()).thenReturn(json.object());when(prompt.authorizations()).thenReturn(json.object());when(components.require(a,b(6),"TOOL",id(1),"EVALUATION_RESULTS")).thenReturn(assembler);when(assembler.authorizations()).thenReturn(json.object());when(assembler.sourceArtifact()).thenReturn(b(30));when(assembler.canonicalDefinition()).thenReturn(assembly);var request=assembly.putObject("request");request.set("input_schema_ref",json.tree(definition().nodeBindings().get(0).inputSchema()));request.set("output_schema_ref",json.tree(definition().nodeBindings().get(0).outputSchema()));
 }
 @BeforeEach void open(){scope=TenantScope.open(new TenantScope.Identity(id(100),id(101),BigInteger.ONE,BigInteger.ONE,BigInteger.ONE));TransactionSynchronizationManager.setActualTransactionActive(true);}
 @AfterEach void close(){TransactionSynchronizationManager.clear();scope.close();}
 @Test void actualClosureRequiresEverySeparateAuthorityAndRechecks()throws Exception{var proof=deps.require(a,definition());assertEquals(5,proof.versions().size());proof.requireCurrent();verify(candidate,times(2)).requireUnchanged();verify(prompt,times(2)).requireUnchanged();verify(assembler,times(2)).requireUnchanged();verify(policy,times(2)).requireUnchanged();}
 @Test void missingExplicitPromptMembershipFails(){manifest.putArray("prompt_revisions");assertThrows(TenantAccessException.class,()->deps.require(a,definition()));verifyNoInteractions(capabilities);}
 @Test void extraModelNodeCannotBeIgnored(){when(policyDefinition.bindings()).thenReturn(List.of(new AgentExecutionPolicyProtocol.NodeBinding("N01",b(4),b(20),b(21),null,json.object(),List.of()),new AgentExecutionPolicyProtocol.NodeBinding("N02",b(4),b(20),b(21),null,json.object(),List.of())));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
 @Test void implicitFirstRoleIsRejected(){when(policyDefinition.bindings()).thenReturn(List.of(new AgentExecutionPolicyProtocol.NodeBinding("N01",b(44),b(20),b(21),null,json.object(),List.of())));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
 @Test void assemblerMustMatchRegisteredInputSchema(){((com.fasterxml.jackson.databind.node.ObjectNode)assembly.at("/request/input_schema_ref")).put("schema_sha256","c".repeat(64));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
 @Test void assemblerMustAppearAsExactCandidateConsumer(){((com.fasterxml.jackson.databind.node.ObjectNode)manifest.at("/input_output_schema_refs/0")).put("consumer_version_id",id(66));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
 @Test void anotherPolicyCannotBeSubstituted(){when(candidate.executionPolicy()).thenReturn(b(33));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
 @Test void modelConnectionVerificationDoesNotSupplyPrompt()throws Exception{when(capabilities.require(a,b(5),"PROMPT",id(1),"EVALUATION_RESULTS")).thenThrow(new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.DEPENDENCY_UNAVAILABLE));assertThrows(TenantAccessException.class,()->deps.require(a,definition()));}
}
